from scipy.optimize import least_squares
def model(p):
    F0,w,ph,c,q,k,pp,b,d=p
    return F0*np.cos(w*t+ph) - c*np.sign(v)*np.abs(v)**q - k*np.sign(x)*np.abs(x)**pp - b*x**3 - d
best=None
for w0 in [0.5,1,1.5,2,3]:
    for ph0 in [0,1.5,3]:
        try:
            r=least_squares(lambda p: model(p)-dv_dt, [5,w0,ph0,1,1,1,1,0.1,0.1],max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
print(best.x, 1-np.var(best.fun)/np.var(dv_dt), np.mean(best.fun**2)/np.var(dv_dt))

base=[np.ones_like(t),x,x**2,x**3,v,v*np.abs(v),v**3,x*v,t*v,t*x,t]
